// A volatility alert just fired; explain it. Everything factual -- the move,
// what the rest of the market did in the same hour, how old each headline is --
// is computed here, and the model may only add a *reason*, by citing one of
// the numbered headlines. Compose turns [n] into a link and drops any number
// that does not exist.
const ev = $('Webhook').first().json.body || {};
const d = $json;
const coins = (d.coins || []).filter((x) => typeof x.price === 'number');
const c = coins.find((x) => x.symbol === ev.symbol) || coins.find((x) => x.ticker === ev.ticker);
if (!c) throw new Error('coin not in digest: ' + (ev.ticker || ev.symbol));

const pct = (v) => (typeof v === 'number' ? `${v >= 0 ? '+' : ''}${v.toFixed(2)}%` : 'n/a');
const fmt = (p) => {
  if (typeof p !== 'number') return 'n/a';
  if (p >= 1000) return p.toLocaleString('en-US', { maximumFractionDigits: 0 });
  if (p >= 1) return p.toFixed(2);
  return p.toPrecision(4);
};
const now = Date.now() / 1000;
const ago = (ts) => {
  if (!ts) return 'время неизвестно';
  const m = Math.max(0, Math.round((now - ts) / 60));
  return m < 90 ? `${m} мин назад` : `${Math.round(m / 60)} ч назад`;
};

// Was it the market or just this coin? Decided here from the tracker's own
// 1h changes, not left to the model.
const up = ev.direction === 'up';
const others = coins.filter((x) => x !== c && typeof x.change_1h === 'number');
const same = others.filter((x) => (up ? x.change_1h >= 1 : x.change_1h <= -1)).length;
const avg1h = others.length ? others.reduce((a, x) => a + x.change_1h, 0) / others.length : null;
const btc = coins.find((x) => x.ticker === 'BTC');
let scope = 'partial';
if (others.length && same >= Math.ceil(others.length * 0.6) && Math.abs(avg1h) >= 1.5) scope = 'market';
else if (avg1h === null || Math.abs(avg1h) < 1) scope = 'solo';
const SCOPE = {
  market: 'движение всего рынка — большинство монет шли в ту же сторону',
  solo: 'монета двигалась одна — остальной рынок почти стоял',
  partial: 'рынок двигался в ту же сторону, но слабее',
};
const marketLine = [
  btc && btc !== c ? `BTC ${pct(btc.change_1h)}` : null,
  avg1h !== null ? `в среднем по остальным ${pct(avg1h)}` : null,
  others.length ? `в ту же сторону ${same} из ${others.length}` : null,
].filter(Boolean).join(' · ');

const refs = [];
const line = (h) => {
  refs.push({ url: h.url, source: h.source });
  const kind = h.kind === 'exchange' ? ', объявление биржи' : '';
  return `[${refs.length}] (${h.source}${kind}, ${ago(h.ts)}) ${h.title}`;
};
const coinNews = (c.headlines || []).map(line);
const marketNews = ((d.market || {}).headlines || []).map(line);

const system = [
  'Ты объясняешь резкое движение криптовалюты для Telegram. Ответ: 1-3 коротких предложения по-русски, до 60 слов.',
  'Цифры движения и рынка уже напечатаны над твоим текстом. НЕ повторяй их.',
  'Причину называй, только если её прямо подтверждает заголовок из списка, и ссылайся на него номером в квадратных скобках, например [3].',
  'Свежие заголовки (минуты или несколько часов назад) важнее: заголовок суточной давности редко объясняет резкий час.',
  'Объявления бирж (Binance, OKX, Bybit, KuCoin, Bitget) официальные: делистинг, остановка депозитов, листинг или обновление сети часто и есть причина.',
  'Если это движение всего рынка, скажи, что монета шла вместе с рынком, и назови причину рынка, если она есть в заголовках.',
  'Если подходящего заголовка нет, напиши «явной новостной причины пока нет» и на что это похоже: на движение всего рынка или на локальное движение монеты (например, крупные сделки).',
  'Нельзя: придумывать новости, события и источники. Причина должна совпадать с направлением: рост не объясняют плохими новостями, падение — хорошими.',
  'Без markdown, эмодзи и HTML. Тикеры латиницей.',
].join('\n');
const system_json = system + '\n\nОтветь строго JSON-объектом: {"text": "..."}';

const user = [
  `Движение: ${c.ticker} (${c.name}) ${up ? 'вырос' : 'упал'} на ${Math.abs(ev.move_pct).toFixed(2)}% за ${ev.window_min || 60} мин: с $${fmt(ev.anchor)} до $${fmt(ev.price)}.`,
  `За 24 часа: ${pct(c.change24h)}.`,
  `Рынок за последний час: ${marketLine || 'нет данных'}. Вывод по данным: ${SCOPE[scope]}.`,
  '',
  coinNews.length ? `Новости по ${c.ticker} (включая объявления бирж):\n${coinNews.join('\n')}` : `Новостей по ${c.ticker} нет.`,
  '',
  marketNews.length ? `Новости рынка:\n${marketNews.join('\n')}` : 'Новостей рынка нет.',
].join('\n');

return [{ json: {
  system, system_json, user, refs,
  schema: { type: 'object', properties: { text: { type: 'string' } }, required: ['text'] },
  ticker: c.ticker, move_pct: ev.move_pct, direction: ev.direction, urgent: !!ev.urgent,
  window_min: ev.window_min || 60, scope, marketLine, reply_to: ev.message_id || null,
} }];

// Free models sometimes answer 200 with an error body or prose. Only a JSON
// object with a non-empty "text" goes on; anything else falls back to Ollama.
const r = $json;
let c = r?.choices?.[0]?.message?.content;
let ok = false;
if (typeof c === 'string') {
  c = c.trim().replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
  try { const o = JSON.parse(c); ok = !!(o && typeof o.text === 'string' && o.text.trim()); } catch (e) { ok = false; }
}
return [{ json: { ...r, ok } }];

// The heading and the market line are printed by code; the model's sentence
// goes underneath, with [n] turned into links. Sent as a reply to the alert.
const r = $json;
let raw = (r?.message?.content ?? r?.choices?.[0]?.message?.content ?? '').trim();
raw = raw.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
let out;
try { out = JSON.parse(raw); } catch (e) { throw new Error('model did not return JSON: ' + raw.slice(0, 300)); }

const p = $('Build prompt').first().json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const pct = (v) => (typeof v === 'number' ? `${v >= 0 ? '+' : ''}${v.toFixed(2)}%` : 'n/a');
const cite = (s) => esc(String(s || '').replace(/<[^>]*>/g, ''))
  .replace(/(?:\s*\[\d+(?:\s*,\s*\d+)*\])+/g, (group) => {
    const seen = new Set();
    const links = (group.match(/\d+/g) || []).map(Number)
      .filter((n) => p.refs[n - 1] && p.refs[n - 1].url)
      .filter((n) => { const k = p.refs[n - 1].source; if (seen.has(k)) return false; seen.add(k); return true; })
      .slice(0, 2)
      .map((n) => `<a href="${esc(p.refs[n - 1].url)}">${esc(p.refs[n - 1].source)}</a>`);
    return links.length ? ` (${links.join(', ')})` : '';
  })
  .trim();

const icon = p.direction === 'up' ? '📈' : '📉';
const model = String(r.model || '');
const text = [
  `🔎 ${icon} <b>Почему ${esc(p.ticker)} ${pct(p.move_pct)} за ${p.window_min} мин</b>`,
  cite(out.text) || '<i>нет объяснения</i>',
  p.marketLine ? `<i>Рынок за час: ${esc(p.marketLine)}</i>` : '',
  `<i>🤖 ${esc(model.replace(/:free$/, '') || 'unknown')} · ${model.includes('/') ? 'OpenRouter' : 'локально, резервная модель'}</i>`,
].filter(Boolean).join('\n\n');
return [{ json: { text, reply_to: p.reply_to } }];
